import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {
    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> body)
            throws InvalidClaimException {
        body.set(ClaimInput.from(request));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;

/**
 * A validated claim request. {@code date} is null when left blank: the sheet's today.
 * {@code corrects} is the number of the claim a correction (a negative amount) corrects; null for
 * any other claim.
 */
public record ClaimInput(BigDecimal amount, LocalDate date, String note, String corrects) {
    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,15}(\\.\\d{1,2})?");
    private static final Pattern NUMBER = Pattern.compile("\\d{1,9}|.{1,190}-\\d{1,9}");

    /** A claim request checked by the claim form's rules. */
    public static ClaimInput from(ClaimRequest request) throws InvalidClaimException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (amount.isEmpty()) throw new InvalidClaimException("An amount is required");
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("An amount is a number with up to two decimals");
        }
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("A date is yyyy-MM-dd");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        if (note.length() > 1000) throw new InvalidClaimException("A note is at most 1000 characters");
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String rawCorrects = request.corrects() == null ? "" : request.corrects().trim();
        String corrects = null;
        if (value.signum() < 0) {
            if (rawCorrects.isEmpty()) {
                throw new InvalidClaimException("A negative amount is a correction: name the claim it corrects");
            }
            if (!NUMBER.matcher(rawCorrects).matches()) {
                throw new InvalidClaimException("A correction names a claim by its number");
            }
            corrects = rawCorrects;
        } else if (!rawCorrects.isEmpty()) {
            throw new InvalidClaimException("Only a negative amount corrects a claim");
        }
        return new ClaimInput(value, date, note, corrects);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** A new DRAFT claim, its due-by fixed now: its date plus the terms of its person's grade on that date. */
public class BuildClaim {
    public void build(@Val ClaimInput input, @Val Sheet sheet, @Val Person person, SettingsRepository settings,
            Out<Claim> claimOut) {
        LocalDate date = input.date() == null ? sheet.today() : input.date();
        Claim claim = new Claim(null, sheet.id(), person.getId(), input.amount(), date, input.note(),
                ClaimStatus.DRAFT, null, null, null);
        claim.setCorrects(input.corrects());
        claim.setDueBy(date.plusDays(settings.find(sheet.id()).termsFor(person.gradeOn(date), date)));
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/**
 * A correction must name, by number, a SETTLED claim of the same person; any other claim names
 * none.
 */
public class CheckCorrection {
    public void check(@Val Claim claim, ClaimRepository repository) throws InvalidClaimException {
        String corrects = claim.getCorrects();
        if (corrects == null) return;
        Claim corrected = repository.findByPerson(claim.getSheetId(), claim.getPersonId()).stream()
                .filter((c) -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED)
                .findFirst().orElse(null);
        if (corrected == null) {
            throw new InvalidClaimException("A correction names a settled claim of the same person");
        }
        // A correction rounds by the date of the claim it corrects.
        claim.setCorrectedDate(corrected.getDate());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Gives a claim being opened its number (the sheet's next, or the next within its period); refused
 * when another request opened it first.
 */
public class NumberClaim {
    public void number(@Val Sheet sheet, @Val Claim claim, ClaimRepository repository, SettingsRepository settings,
            PeriodRepository periods) throws InvalidClaimStatusException {
        if (!repository.markOpened(claim)) throw new InvalidClaimStatusException(ClaimStatus.DRAFT, ClaimStatus.OPEN);
        claim.setNumber(ClaimNumbers.next(sheet, claim, settings.find(sheet.id()), periods, repository));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveClaim {
    public void save(@Val Claim claim, ClaimRepository repository) {
        repository.save(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the saved claim. Runs after every rule has passed, so a refused change writes nothing. */
public class AuditClaimAdded {
    public void audit(@Val Sheet sheet, @Val Person person, @Val Claim claim,
            HttpServletRequest request, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_ADDED", sheet, Audit.user(request), person, claim));
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim as the screen sends it, to add or to edit: an amount (up to two decimals; negative only
 * for a correction), a date (yyyy-MM-dd, or blank for the sheet's today), a note (may be empty)
 * and, for a correction, the number of the settled claim it corrects (blank otherwise).
 */
public record ClaimRequest(String amount, String date, String note, String corrects) {
}

